// This file is generated by AI.

// 实时预览的行号指示器状态。
//
// 预览面板的「预览」开关打开时, 编辑器把当前行同步给引擎 (`preview.command.sync-scene`)
// 并**在行号旁立起一个指示器**; 引擎回灌 `stage.snapshot.updated` 之后, 指示器换成
// "已执行"或"已越过"。这里只负责这份状态怎么随引擎事件演化, 不涉及 Monaco ——
// 画成什么样子见 `editor/gutter-live-preview.ts`。
//
// 三处容易踩的坑, 都在下面显式钉住:
//
// 1. **引擎上报的是"停止指针"**: 编辑器把 Monaco 行号 L (1 起算) 当作 `sentenceId` 发出去,
//    而 WebGAL 的语句号就是 0 起算的行号, 因此"执行第 L 行"= 让指针推到 L。快进循环
//    `while (currentSentenceId < L)` 执行的正是第 L 行本身, 停下后回灌的 `sentenceId`
//    恰好等于 L —— 所以「回灌值 == 指示器的行号」才是"这一行跑完了"。
// 2. **回灌是异步的, 会迟到**: 光标一移就换目标, 而引擎上一条快进的回灌可能后到。
//    把"回灌值不等于目标行"当成失败, 就会出现"明明抵达了却说没执行到"的假失败
//    (第 2 个需求的根因)。因此这里把这一类回灌一律读作**预览已经不在目标行上** ——
//    也就是"已越过", 而不是失败。
// 3. **对同一行的重复同步不该把结果打回等待**: 原地打字会让同一行反复触发同步,
//    每次都把已落定的结果清掉就会一直闪 (由 `preview/client.ts` 决定初始状态)。

/** 指示器状态 */
export type LivePreviewPhase =
  /** 已发出同步, 等引擎落定 */
  | 'executing'
  /** 引擎回灌确认执行到了这一行 */
  | 'done'
  /** 预览已经越过 / 离开了这一行 (不再等待) */
  | 'passed'
  /** 快进超时, 没能执行到这一行 */
  | 'failed';

/** 当前编辑器指示器指向的一行 */
export interface LivePreviewMarker {
  /** 目标场景的文档路径 (指示器只画在这个文档上) */
  docPath: string;
  /** 目标行 (1 起算, 与 Monaco 一致) */
  line: number;
  phase: LivePreviewPhase;
  /** 引擎上报的场景名 (空串表示引擎未报) */
  sceneName: string;
}

export interface StageSnapshotPayload {
  sceneName?: unknown;
  sentenceId?: unknown;
}

export interface FastPreviewTimeoutPayload {
  sceneName?: unknown;
  /** 快进停下的语句指针 */
  sentenceId?: unknown;
  /** 编辑器要求跳转到的语句指针 (与目标行号同值) */
  targetSentenceId?: unknown;
}

/**
 * 本次同步的目标行是否已经执行完。
 *
 * 单独成函数是因为它承载着上面第 1 条约定 —— 可单独测试, 也避免各处各写一份判断。
 */
export function isLivePreviewTargetExecuted(
  marker: Pick<LivePreviewMarker, 'line'>,
  reportedSentenceId: number
): boolean {
  return reportedSentenceId === marker.line;
}

function readString(value: unknown): string | null {
  return typeof value === 'string' ? value : null;
}

function readNumber(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function reportsSameScene(marker: LivePreviewMarker, sceneName: unknown): boolean {
  const reported = readString(sceneName);
  // 引擎没报场景名, 或者本机拿不到场景名, 都不足以否定这条事件
  return reported === null || marker.sceneName === '' || reported === marker.sceneName;
}

/**
 * 这条 `stage.snapshot.updated` 是否还在说当前这次同步。
 *
 * 这里的闸门只挡"别的场景" —— 同场景内指针值是几都照收: 等于目标行是"执行到了",
 * 不等于目标行是"预览不在这一行上了"(见 `applyStageSnapshotToLivePreviewMarker`)。
 * 曾经的写法是"指针越过目标行就丢弃", 于是迟到的旧回灌既不算成功也不算越过,
 * 指示器就一直停在等待里。
 */
export function isStageSnapshotForLivePreviewMarker(marker: LivePreviewMarker, payload: StageSnapshotPayload): boolean {
  return reportsSameScene(marker, payload.sceneName);
}

/**
 * 这条 `preview.event.fast-preview-timeout` 是否还在说当前这次同步。
 *
 * 超时事件带的是**发起时**要求跳到的指针, 与目标行号同值, 因此可以直接比对;
 * 对不上说明编辑器已经在别处发了新的同步。
 */
export function isFastPreviewTimeoutForLivePreviewMarker(
  marker: LivePreviewMarker,
  payload: FastPreviewTimeoutPayload
): boolean {
  if (!reportsSameScene(marker, payload.sceneName)) return false;

  const targetSentenceId = readNumber(payload.targetSentenceId);
  return targetSentenceId === null || targetSentenceId === marker.line;
}

/**
 * 按 `stage.snapshot.updated` 推进指示器。
 *
 * 只有"指针 == 目标行"才叫**确证执行到了**, 也就是绿色 —— 快进循环跑的正是目标行本身,
 * 因此这是唯一能确证的方式。
 *
 * "指针 != 目标行"则退一步读作"预览不在这条路上", 给黄色"已越过": 引擎停下时可能报出
 * **超过**目标行的指针 (目标行是连续执行/多行语句的一部分, 一次 forward 就走过去了),
 * 但那是"跳过去了"而不是"确证执行了", 因此不敢判绿。黄色同时明确、不误报, 且点一下能重跑。
 *
 * 关键是**绿可以覆盖黄与红**: 迟到的旧回灌会先把状态带偏 (报出别的指针), 而引擎每次跳转
 * 落定都会再播报一次目标行, 那才是权威答案; 红 (超时) 同理, 不该因一次陈旧判定就永远留着。
 * 反过来, 已经确证执行过的绿不会被引擎继续往下跑所改写。
 */
export function applyStageSnapshotToLivePreviewMarker(
  marker: LivePreviewMarker,
  payload: StageSnapshotPayload
): LivePreviewMarker {
  const sentenceId = readNumber(payload.sentenceId);
  if (sentenceId === null) return marker;

  if (isLivePreviewTargetExecuted(marker, sentenceId)) {
    return marker.phase === 'done' ? marker : { ...marker, phase: 'done' };
  }

  // 已经确证执行过的结果不再改写; 其余情况都退到"已越过"
  return marker.phase === 'done' ? marker : { ...marker, phase: 'passed' };
}

/** 按 `preview.event.fast-preview-timeout` 推进指示器 (快进没走到目标行即失败)。 */
export function applyFastPreviewTimeoutToLivePreviewMarker(marker: LivePreviewMarker): LivePreviewMarker {
  return marker.phase === 'executing' ? { ...marker, phase: 'failed' } : marker;
}
